 99 |   // Restore account (if signed in) and non-personal device preferences.
100 |   async function loadAccount() {
101 |     try {
102 |       const res = await fetch('/api/profile');
103 |       if (res.ok) {
104 |         const data = await res.json() as { profile?: Profile; language?: Language };
105 |         if (data.profile) setProfile(data.profile);
106 |         if (data.language && LANGUAGES.some(l => l.code === data.language)) setLanguage(data.language);
107 |       }
108 |       const apps = await fetch('/api/applications');
109 |       if (apps.ok) {
110 |         const data = await apps.json() as { applications: Array<{ schemeId: string; status: 'saved' | 'applied' }> };
111 |         const map: Record<string, 'saved' | 'applied'> = {};
112 |         for (const a of data.applications) map[a.schemeId] = a.status;
113 |         setAppliedList(map);
114 |       }
115 |     } catch { /* offline: keep local state */ }
116 |     finally { hydrated.current = true; }
