197 |   async function send(value = text) {
198 |     if (!value.trim() || loading) return;
199 |     recognition.current?.stop();
200 |     setError(''); setLoading(true);
201 |     const prior = messages;
202 |     setMessages(m => [...m, { role: 'user', content: value }]);
203 |     setText('');
204 |     const controller = new AbortController();
205 |     request.current = controller;
206 |     try {
207 |       const res = await fetch('/api/chat', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: value, language, profile, history: prior.slice(-12) }), signal: controller.signal });
208 |       const payload: unknown = await res.json().catch(() => null);
209 |       if (!res.ok) {
210 |         const apiMessage = payload && typeof payload === 'object' && 'error' in payload && typeof payload.error === 'string' ? payload.error : t.error;
211 |         throw new Error(apiMessage);
212 |       }
213 |       const data = payload as ChatResponse;
214 |       if (!data || typeof data.reply !== 'string' || !Array.isArray(data.matches) || !data.profile || !Array.isArray(data.trace)) throw new Error(t.error);
215 |       setProfile(data.profile); setMatches(data.matches); setTrace(data.trace); setMode(data.mode); setSearched(true);
