235 |   function microphone() {
236 |     if (listening) { recognition.current?.stop(); return; }
237 |     const w = window as unknown as { SpeechRecognition?: new () => Recognition; webkitSpeechRecognition?: new () => Recognition };
238 |     const Constructor = w.SpeechRecognition || w.webkitSpeechRecognition;
239 |     if (!Constructor) return;
