306 |   async function toggleSchemeStatus(schemeId: string, status: 'saved' | 'applied') {
307 |     if (!authUser) return;
308 |     const turningOff = appliedList[schemeId] === status;
309 |     const previous = appliedList;
310 |     setAppliedList(cur => {
311 |       const next = { ...cur };
312 |       if (turningOff) delete next[schemeId];
313 |       else next[schemeId] = status;
314 |       return next;
315 |     });
316 |     try {
317 |       const res = turningOff
318 |         ? await fetch(`/api/applications?schemeId=${encodeURIComponent(schemeId)}`, { method: 'DELETE' })
319 |         : await fetch('/api/applications', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ schemeId, status }) });
320 |       if (!res.ok) throw new Error();
321 |     } catch {
322 |       setAppliedList(previous); // roll back the optimistic update
323 |       setError(t.error);
324 |     }
325 |   }
