  1 | // Enhanced browser text-to-speech. This is provider-agnostic: the pure
  2 | // `pickVoice`/`scoreVoice` logic is separated from the browser controller so a
  3 | // cloud TTS (Google / OpenAI / ElevenLabs) can be slotted behind `speak()` later
  4 | // without touching the UI. Everything here is keyless and offline-capable.
  5 | 
  6 | import { speechLocale } from './i18n';
  7 | import type { Language } from './contracts';
  8 | 
  9 | /** Minimal voice shape so selection logic is testable without a browser. */
 10 | export interface VoiceLike {
 11 |   name: string;
 12 |   lang: string;
 13 |   localService?: boolean;
 14 |   default?: boolean;
 15 | }
 16 | 
 17 | /** Heuristic, quality-oriented voice scoring for a target locale. */
 18 | export function scoreVoice(voice: VoiceLike, targetLocale: string): number {
 19 |   const lang = (voice.lang || '').toLowerCase();
 20 |   const target = targetLocale.toLowerCase();
 21 |   const targetBase = target.split('-')[0];
 22 |   let score = 0;
 23 |   if (lang === target) score += 100;
 24 |   else if (lang === targetBase) score += 60;
 25 |   else if (lang.startsWith(targetBase + '-')) score += 55;
 26 |   else return -1; // different language entirely
 27 |   // Offline/local voices avoid network latency and are usually more reliable.
 28 |   if (voice.localService) score += 8;
 29 |   if (voice.default) score += 4;
 30 |   // Names hinting at higher-quality neural voices (varies by platform).
 31 |   const name = voice.name.toLowerCase();
 32 |   if (/natural|neural|premium|enhanced|wavenet|google|online/.test(name)) score += 10;
 33 |   if (/compact|espeak|robotic/.test(name)) score -= 6;
 34 |   return score;
 35 | }
