 37 | /** Pick the best voice for a locale, honoring a user-preferred voice if set. */
 38 | export function pickVoice(voices: VoiceLike[], locale: string, preferredName?: string | null): VoiceLike | null {
 39 |   if (preferredName) {
 40 |     const preferred = voices.find(v => v.name === preferredName);
 41 |     if (preferred) return preferred;
 42 |   }
 43 |   let best: VoiceLike | null = null;
 44 |   let bestScore = -1;
 45 |   for (const voice of voices) {
 46 |     const score = scoreVoice(voice, locale);
 47 |     if (score > bestScore) { bestScore = score; best = voice; }
 48 |   }
 49 |   return bestScore >= 0 ? best : null;
 50 | }
 51 | 
 52 | /** Resolve the device voice list, waiting for the async `voiceschanged` event. */
 53 | export function loadVoices(): Promise<VoiceLike[]> {
 54 |   if (typeof window === 'undefined' || !('speechSynthesis' in window)) return Promise.resolve([]);
 55 |   const existing = window.speechSynthesis.getVoices();
 56 |   if (existing.length) return Promise.resolve(existing);
 57 |   return new Promise(resolve => {
 58 |     let settled = false;
 59 |     const finish = () => {
 60 |       if (settled) return;
 61 |       settled = true;
 62 |       window.speechSynthesis.onvoiceschanged = null;
 63 |       resolve(window.speechSynthesis.getVoices());
 64 |     };
 65 |     window.speechSynthesis.onvoiceschanged = finish;
 66 |     // Some browsers never fire the event; don't hang forever.
 67 |     setTimeout(finish, 1200);
 68 |   });
 69 | }
