 71 | export interface TTSController {
 72 |   supported: boolean;
 73 |   speak: (text: string, language: Language, onDone?: () => void) => void;
 74 |   stop: () => void;
 75 |   setRate: (rate: number) => void;
 76 |   setPreferredVoice: (name: string | null) => void;
 77 | }
 78 | 
 79 | /** Create a browser TTS controller. Call only in the browser. */
 80 | export function createTTS(): TTSController {
 81 |   const supported = typeof window !== 'undefined' && 'speechSynthesis' in window;
 82 |   let preferred: string | null = null;
 83 |   let rate = 1;
 84 |   const stop = () => { if (supported) window.speechSynthesis.cancel(); };
 85 |   const speak = (text: string, language: Language, onDone?: () => void) => {
 86 |     if (!supported || !text.trim()) { onDone?.(); return; }
 87 |     window.speechSynthesis.cancel();
 88 |     const utterance = new SpeechSynthesisUtterance(text);
 89 |     const locale = speechLocale(language);
 90 |     utterance.lang = locale;
 91 |     utterance.rate = rate;
 92 |     utterance.pitch = 1;
 93 |     const apply = (voices: VoiceLike[]) => {
 94 |       const voice = pickVoice(voices, locale, preferred);
 95 |       if (voice) {
 96 |         const native = window.speechSynthesis.getVoices().find(v => v.name === voice.name);
 97 |         if (native) utterance.voice = native;
 98 |       }
 99 |       utterance.onend = () => onDone?.();
100 |       utterance.onerror = () => onDone?.();
101 |       window.speechSynthesis.speak(utterance);
102 |     };
103 |     const cached = window.speechSynthesis.getVoices();
104 |     if (cached.length) apply(cached);
105 |     else void loadVoices().then(apply);
106 |   };
107 |   return {
108 |     supported,
109 |     speak,
110 |     stop,
111 |     setRate: (r: number) => { rate = Math.min(1.6, Math.max(0.6, r)); },
112 |     setPreferredVoice: (name: string | null) => { preferred = name; },
113 |   };
114 | }

  1 | // Session authentication. Passwords are hashed with scrypt (Node crypto) and
  2 | // compared in constant time. Sessions are random 256-bit tokens in an httpOnly
  3 | // cookie. No conversation text or chat history is ever stored — only accounts
  4 | // and the profile each user explicitly saves.
  5 | 
  6 | import { randomBytes, scryptSync, timingSafeEqual } from 'node:crypto';
  7 | import { getDb } from './db';
  8 | 
  9 | export const SESSION_COOKIE = 'knock_session';
 10 | const SESSION_DAYS = 30;
 11 | 
 12 | export interface SessionUser { id: number; name: string; email: string }
 13 | 
 14 | export function hashPassword(password: string): string {
 15 |   const salt = randomBytes(16).toString('hex');
 16 |   const hash = scryptSync(password, salt, 64).toString('hex');
 17 |   return `${salt}:${hash}`;
 18 | }
 19 | 
 20 | export function verifyPassword(password: string, stored: string): boolean {
 21 |   const [salt, hash] = stored.split(':');
 22 |   if (!salt || !hash) return false;
 23 |   const expected = Buffer.from(hash, 'hex');
 24 |   const candidate = scryptSync(password, salt, 64);
 25 |   return expected.length === candidate.length && timingSafeEqual(expected, candidate);
 26 | }
