 28 | export function findUserByEmail(email: string) {
 29 |   const row = getDb().prepare('SELECT id, email, name, password_hash FROM users WHERE email = ?').get(email);
 30 |   return (row as undefined | { id: number; email: string; name: string; password_hash: string }) ?? null;
 31 | }
