 33 | export function createUser(email: string, name: string, password: string): SessionUser {
 34 |   const db = getDb();
 35 |   const result = db.prepare('INSERT INTO users (email, name, password_hash, created_at) VALUES (?, ?, ?, ?)').run(email, name, hashPassword(password), new Date().toISOString());
 36 |   return { id: Number(result.lastInsertRowid), name, email };
 37 | }
 38 | 
 39 | export function createSession(userId: number): string {
 40 |   const db = getDb();
 41 |   // Opportunistic cleanup of expired sessions.
 42 |   db.prepare('DELETE FROM sessions WHERE expires_at < ?').run(new Date().toISOString());
 43 |   const token = randomBytes(32).toString('hex');
 44 |   const expires = new Date(Date.now() + SESSION_DAYS * 86400_000).toISOString();
 45 |   db.prepare('INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)').run(token, userId, expires);
 46 |   return token;
 47 | }
 48 | 
 49 | export function deleteSession(token: string): void {
 50 |   getDb().prepare('DELETE FROM sessions WHERE token = ?').run(token);
 51 | }
 52 | 
 53 | export function readSessionCookie(request: Request): string | null {
 54 |   const header = request.headers.get('cookie');
 55 |   if (!header) return null;
 56 |   for (const part of header.split(';')) {
 57 |     const [key, ...rest] = part.trim().split('=');
 58 |     if (key === SESSION_COOKIE) return decodeURIComponent(rest.join('='));
 59 |   }
 60 |   return null;
 61 | }
 62 | 
 63 | export function getSessionUser(request: Request): SessionUser | null {
 64 |   const token = readSessionCookie(request);
 65 |   if (!token || token.length < 32 || !/^[a-f0-9]+$/.test(token)) return null;
 66 |   const row = getDb().prepare(
 67 |     'SELECT u.id, u.name, u.email, s.expires_at FROM sessions s JOIN users u ON u.id = s.user_id WHERE s.token = ?',
 68 |   ).get(token);
 69 |   if (!row) return null;
 70 |   const session = row as { id: number; name: string; email: string; expires_at: string };
 71 |   if (new Date(session.expires_at).getTime() < Date.now()) {
 72 |     deleteSession(token);
 73 |     return null;
 74 |   }
 75 |   return { id: session.id, name: session.name, email: session.email };
 76 | }
