 9 | export async function readJsonBody(request: Request, maxBytes = 64000): Promise<{ ok: true; body: unknown } | { ok: false; status: 400 | 413 }> {
10 |   const reader = request.body?.getReader();
11 |   if (!reader) return { ok: false, status: 400 };
12 |   const decoder = new TextDecoder();
13 |   let raw = '';
14 |   let size = 0;
15 |   while (true) {
16 |     const { done, value } = await reader.read();
17 |     if (done) break;
18 |     size += value.byteLength;
19 |     if (size > maxBytes) { await reader.cancel(); return { ok: false, status: 413 }; }
20 |     raw += decoder.decode(value, { stream: true });
21 |   }
22 |   raw += decoder.decode();
23 |   try { return { ok: true, body: JSON.parse(raw) }; }
24 |   catch { return { ok: false, status: 400 }; }
25 | }
