27 | // Lightweight per-process throttling for auth endpoints (not distributed protection).
28 | const attempts = new Map<string, { count: number; resetAt: number }>();
29 | 
30 | export function throttle(key: string, limit = 12, windowMs = 15 * 60_000): boolean {
31 |   const now = Date.now();
32 |   const entry = attempts.get(key);
33 |   if (!entry || entry.resetAt < now) {
34 |     attempts.set(key, { count: 1, resetAt: now + windowMs });
35 |     return true;
36 |   }
37 |   entry.count += 1;
38 |   return entry.count <= limit;
39 | }

