// Email delivery seam. This prototype has no transactional mail provider
// configured, so a "send" logs a redacted confirmation to the server console and
// (outside production) returns the link so the UI can offer a dev-only button to
// complete verification. To make delivery real, wire a provider (Resend, SES,
// SMTP) inside sendVerificationEmail and flip `delivered` to true when accepted.
//
// Privacy: we never log the recipient address in full (only a redacted form) and
// never log passwords or API keys.

export interface VerificationEmail {
  /** True only when a real provider accepted the message. */
  delivered: boolean;
  /** Non-production only: link a tester can open to verify. Null in production. */
  devLink: string | null;
}

function appBaseUrl(): string {
  return process.env.PUBLIC_APP_URL || 'http://localhost:3000';
}

export function verificationLink(rawToken: string): string {
  return `${appBaseUrl()}/verify?token=${encodeURIComponent(rawToken)}`;
}

/** Redact an address for logs: "asha@example.com" -> "a***@example.com". */
export function redactEmail(email: string): string {
  const at = email.indexOf('@');
  if (at <= 0) return '***';
  const name = email.slice(0, at);
  const domain = email.slice(at);
  return `${name[0]}***${domain}`;
}

export async function sendVerificationEmail(email: string, rawToken: string): Promise<VerificationEmail> {
  const link = verificationLink(rawToken);
  const isProd = process.env.NODE_ENV === 'production';

  // A real provider would be called here. Until then, surface the link in the
  // server console (redacted recipient) so it is discoverable during development.
  // eslint-disable-next-line no-console
  console.log(`[email] verification link for ${redactEmail(email)}: ${link}`);

  return { delivered: false, devLink: isProd ? null : link };
}

export const passwordChangeSchema = z.object({
  currentPassword: z.string().min(1).max(128),
  newPassword: z.string().min(8).max(128),
}).strict();

export const verifySchema = z.object({
  token: z.string().trim().min(16).max(128).regex(/^[a-f0-9]+$/i, 'invalid token'),
}).strict();

export const resendSchema = z.object({
  email: emailField,
}).strict();

