/**
 * Split text into speakable chunks. Long, unbroken utterances silently stall in
 * some browsers (Chrome pauses after ~15s and never fires `onend`), so we speak
 * short sentence-sized pieces sequentially instead. Pure and unit-testable.
 */
export function chunkText(text: string, maxLen = 180): string[] {
  const normalized = text.replace(/\s+/g, ' ').trim();
  if (!normalized) return [];
  const sentences = normalized.match(/[^.!?।]+[.!?।]*/g) ?? [normalized];
  const chunks: string[] = [];
  let current = '';
  for (const raw of sentences) {
    const sentence = raw.trim();
    if (!sentence) continue;
    if ((current + ' ' + sentence).trim().length > maxLen) {
      if (current.trim()) chunks.push(current.trim());
      if (sentence.length > maxLen) {
        for (let i = 0; i < sentence.length; i += maxLen) {
          const piece = sentence.slice(i, i + maxLen).trim();
          if (piece) chunks.push(piece);
        }
        current = '';
      } else {
        current = sentence;
      }
    } else {
      current = (current + ' ' + sentence).trim();
    }
  }
  if (current.trim()) chunks.push(current.trim());
  return chunks.length ? chunks : [normalized];
}

export interface TTSController {
  supported: boolean;
  speak: (text: string, language: Language, onDone?: () => void) => void;
  stop: () => void;
  setRate: (rate: number) => void;
  setPreferredVoice: (name: string | null) => void;
}

/** Create a browser TTS controller. Call only in the browser. */
export function createTTS(): TTSController {
  const supported = typeof window !== 'undefined' && 'speechSynthesis' in window;
  let preferred: string | null = null;
  let rate = 1;
  // Monotonic token: bumped on every speak/stop so stale callbacks are ignored.
  let token = 0;

  const stop = () => {
    token += 1;
    if (supported) window.speechSynthesis.cancel();
  };

  const speak = (text: string, language: Language, onDone?: () => void) => {
    if (!supported || !text.trim()) { onDone?.(); return; }
    window.speechSynthesis.cancel();
    const mine = ++token;
    const locale = speechLocale(language);
    const chunks = chunkText(text);
    let index = 0;

    const next = (voices: VoiceLike[]): void => {
      if (mine !== token) return; // cancelled or superseded
      if (index >= chunks.length) { onDone?.(); return; }
      const utterance = new SpeechSynthesisUtterance(chunks[index++]);
      utterance.lang = locale;
      utterance.rate = rate;
      utterance.pitch = 1;
      const voice = pickVoice(voices, locale, preferred);
      if (voice) {
        const native = window.speechSynthesis.getVoices().find(v => v.name === voice.name);
        if (native) utterance.voice = native;
      }
      utterance.onend = () => {
        if (mine !== token) return;
        window.speechSynthesis.resume(); // keep-alive against browser stalls
        next(voices);
      };
      utterance.onerror = () => {
        if (mine !== token) return;
        next(voices); // skip the failed chunk and carry on
      };
      window.speechSynthesis.speak(utterance);
    };

    const cached = window.speechSynthesis.getVoices();
    if (cached.length) next(cached);
    else void loadVoices().then(next);
  };

  return {
    supported,
    speak,
    stop,
    setRate: (r: number) => { rate = Math.min(1.6, Math.max(0.6, r)); },
    setPreferredVoice: (name: string | null) => { preferred = name; },
  };
}

