/* ===== Professional auth & verification shell ===== */
.auth-shell{width:100%;max-width:940px;display:grid;grid-template-columns:minmax(0,0.9fr) minmax(0,1.1fr);
  background:var(--white);border:1px solid var(--line);border-radius:22px;overflow:hidden;
  box-shadow:0 30px 80px #273c2424,0 2px 8px #273c2410}
