  color:#eef3ec;padding:38px 34px;display:flex;flex-direction:column;gap:18px}
.auth-aside .brand{color:#fff;font-size:30px}
.auth-aside .brand-dot{color:var(--saffron)}
.auth-aside-title{font-size:29px;line-height:1.15;font-weight:650;color:#fff;letter-spacing:-.5px;margin-top:8px}
.auth-aside-title em{font-style:normal;color:#e7c489}
.auth-aside-sub{font-size:13px;line-height:1.65;color:#c6d3c6;margin:0}
.auth-perks{list-style:none;margin:8px 0 0;padding:0;display:flex;flex-direction:column;gap:13px}
.auth-perks li{display:flex;align-items:flex-start;gap:11px;font-size:12.5px;line-height:1.5;color:#dbe6da}
.auth-perks li svg{margin-top:1px;color:#e7c489;flex:0 0 auto}
.auth-aside-foot{margin-top:auto;display:flex;align-items:center;gap:8px;font-size:10.5px;color:#a9bbab;padding-top:18px;border-top:1px solid #ffffff1f}
.auth-panel{padding:32px 34px;display:flex;flex-direction:column;gap:14px;justify-content:center}
.auth-panel-top{display:flex;justify-content:flex-end}
.auth-panel .auth-title{font-size:23px}
.auth-panel .auth-sub{font-size:11.5px}

.field-hint{font-size:9.5px;font-weight:500;color:var(--muted);line-height:1.4}
.field-hint.warn{color:#a2492f}
.password-wrap{position:relative;display:flex}
.password-wrap input{padding-right:44px}
.password-toggle{position:absolute;right:6px;top:50%;transform:translateY(-50%);width:30px;height:30px;
  display:flex;align-items:center;justify-content:center;border-radius:7px;color:var(--muted)}
.password-toggle:hover{background:#eef1e8;color:var(--forest)}
.strength{display:flex;align-items:center;gap:9px;margin-top:2px}
.strength-track{display:flex;gap:4px;flex:1}
.strength-seg{height:5px;flex:1;border-radius:99px;background:#e7e8de}
.strength-seg.on{background:#c98a52}
.strength-seg.on.s2{background:#c9a452}
.strength-seg.on.s3{background:#8aa867}
.strength-seg.on.s4{background:#4f8a52}
.strength-label{font-size:9px;font-weight:650;color:var(--forest);min-width:36px;text-align:right}

.verify-panel{display:flex;flex-direction:column;align-items:center;text-align:center;gap:12px;padding:8px 0 2px}
.verify-badge{width:62px;height:62px;border-radius:50%;display:flex;align-items:center;justify-content:center;
  background:#eef3e8;color:var(--forest);border:1px solid #d7e0cc}
.verify-badge.ok{background:#e6f2e4;color:#2f7a45;border-color:#b7d9bd}
.verify-badge.bad{background:#fbeae5;color:#a2492f;border-color:#ecc7bb}
.verify-email{margin:0;font-size:13px;font-weight:700;color:var(--deep);background:#f4f6ef;
  border:1px solid var(--line);border-radius:8px;padding:8px 14px;word-break:break-all}
.verify-spinner{width:46px;height:46px;border-radius:50%;border:3px solid #dfe6d8;border-top-color:var(--forest);
  animation:auth-spin .9s linear infinite}
.verify-panel .auth-submit{width:100%}
.verify-panel .auth-error,.verify-panel .account-sync{width:100%}
.link-button{text-decoration:none}
.link-button:hover{background:#17382c}

/* Read-aloud active state */
.read-button.reading{color:var(--forest);font-weight:700}

@media (max-width:820px){
  .auth-shell{grid-template-columns:1fr;max-width:440px}
