// Microphone diagnostics. The Web Speech API reports failures through opaque
// error codes (SpeechRecognitionErrorEvent.error) and the getUserMedia pre-flight
// reports DOMException names. We normalise both into a small set of causes so the
// UI can show one specific, actionable message instead of a vague catch-all.

export type MicErrorKind =
  | 'ok'
  | 'no-speech'     // silence — transient, keep listening
  | 'aborted'       // intentional stop — ignore
  | 'blocked'       // permission denied / not-allowed / service-not-allowed
  | 'insecure'      // not a secure context (needs https:// or localhost)
  | 'no-mic'        // no capture device present
  | 'in-use'        // device busy in another app
  | 'network'       // browser speech service unreachable (it is processed online)
  | 'language'      // chosen locale not supported by the speech service
  | 'unsupported'   // browser has no SpeechRecognition at all
  | 'unknown';

/** Classify a Web Speech API error code. */
export function classifySpeechError(code: string | null | undefined): MicErrorKind {
  switch (code) {
    case 'no-speech': return 'no-speech';
    case 'aborted': return 'aborted';
    case 'not-allowed':
    case 'service-not-allowed': return 'blocked';
    case 'audio-capture': return 'no-mic';
    case 'network': return 'network';
    case 'language-not-supported': return 'language';
    case 'bad-grammar': return 'unknown';
    default: return 'unknown';
  }
}

/** Classify a getUserMedia DOMException name from the mic pre-flight. */
export function classifyGetUserMediaError(name: string | null | undefined): MicErrorKind {
  switch (name) {
    case 'NotAllowedError':
    case 'SecurityError': return 'blocked';
    case 'NotFoundError':
    case 'OverconstrainedError':
    case 'DevicesNotFoundError': return 'no-mic';
    case 'NotReadableError':
    case 'TrackStartError': return 'in-use';
    case 'AbortError': return 'aborted';
    default: return 'unknown';
  }
}

/** Whether this browser exposes the SpeechRecognition API at all. */
export function speechRecognitionSupported(): boolean {
  if (typeof window === 'undefined') return false;
  const w = window as unknown as { SpeechRecognition?: unknown; webkitSpeechRecognition?: unknown };
  return Boolean(w.SpeechRecognition || w.webkitSpeechRecognition);
}

