/** Specific, actionable message for each mic failure cause. */
function micErrorText(kind: MicErrorKind): string {
  switch (kind) {
    case 'unsupported': return t.micUnsupported;
    case 'blocked': return t.micBlocked;
    case 'insecure': return t.micInsecure;
    case 'no-mic': return t.micNoDevice;
    case 'in-use': return t.micBusy;
    case 'network': return t.micNetwork;
    case 'language': return t.micLanguage;
    default: return t.micGeneric;
  }
}

/**
 * Pre-flight: confirm a secure context and explicitly request microphone access
 * so the browser shows its permission prompt and we can report a concrete reason
 * (no device / denied / busy) instead of a vague failure.
 */
async function requestMic(): Promise<MicErrorKind> {
  if (typeof window === 'undefined') return 'unsupported';
  if (!window.isSecureContext) return 'insecure';
  const md = navigator.mediaDevices;
  if (!md || typeof md.getUserMedia !== 'function') {
    // No getUserMedia: if SpeechRecognition exists, let it attempt its own flow.
    return speechRecognitionSupported() ? 'ok' : 'unsupported';
  }
  try {
    const stream = await md.getUserMedia({ audio: true });
    stream.getTracks().forEach(track => track.stop());
    return 'ok';
  } catch (err) {
    return classifyGetUserMediaError((err as { name?: string } | null)?.name);
  }
}

async function microphone() {
  if (micActive.current || listening) { stopListening(); return; }
  const w = window as unknown as { SpeechRecognition?: new () => Recognition; webkitSpeechRecognition?: new () => Recognition };
  const Constructor = w.SpeechRecognition || w.webkitSpeechRecognition;
  if (!Constructor) { setError(t.micUnsupported); return; }
  setError('');
  micActive.current = true; // claim the mic for the whole operation (incl. pre-flight)
  setListening(true);
  const pre = await requestMic();
  if (pre !== 'ok') { micActive.current = false; setListening(false); setError(micErrorText(pre)); return; }
  if (!micActive.current) return; // stopped during the pre-flight
  const rec = new Constructor();
  recognition.current = rec;
  rec.lang = speechLocale(language);
  rec.interimResults = true;
  rec.continuous = true;
  const base = text.trim();

